#!/usr/bin/python
"""Reconcile invoice totals and payments using integer cents."""
import csv
import os
import re
import tempfile

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INVOICES = os.path.join(BASE, "invoices.csv")
PAYMENTS = os.path.join(BASE, "payments.csv")
BALANCES = os.path.join(BASE, "balances.csv")
REJECTED = os.path.join(BASE, "rejected.csv")
CENT_AMOUNT = re.compile(r"^[+-]?[0-9]+$")


def parse_cents(value):
    value = value.strip()
    if not CENT_AMOUNT.match(value):
        raise ValueError("not an integer cent amount")
    return int(value)


def load_invoices():
    invoices = {}
    order = []
    with open(INVOICES, newline="", encoding="utf-8-sig") as source:
        rows = csv.reader(source)
        try:
            header = next(rows)
        except StopIteration:
            raise ValueError("invoices.csv is empty")
        if header != ["invoice_id", "total_cents"]:
            raise ValueError("unexpected invoices.csv header")
        for line_number, row in enumerate(rows, 2):
            if len(row) != 2 or not row[0]:
                raise ValueError("malformed invoices.csv row %d" % line_number)
            invoice_id, total_text = row
            if invoice_id in invoices:
                raise ValueError("duplicate invoice_id %s" % invoice_id)
            try:
                invoices[invoice_id] = parse_cents(total_text)
            except ValueError:
                raise ValueError("malformed total_cents on invoices.csv row %d" % line_number)
            order.append(invoice_id)
    return invoices, order


def reconcile(invoices):
    balances = dict(invoices)
    rejected = []
    seen_payment_ids = set()
    with open(PAYMENTS, newline="", encoding="utf-8-sig") as source:
        rows = csv.reader(source)
        try:
            header = next(rows)
        except StopIteration:
            raise ValueError("payments.csv is empty")
        if header != ["payment_id", "invoice_id", "amount_cents"]:
            raise ValueError("unexpected payments.csv header")
        for row in rows:
            fields = (row + ["", "", ""])[:3]
            payment_id, invoice_id, amount_text = fields
            reasons = []
            if len(row) != 3:
                reasons.append("malformed_row")
            if not payment_id:
                reasons.append("missing_payment_id")
            elif payment_id in seen_payment_ids:
                reasons.append("duplicate_payment_id")
            else:
                seen_payment_ids.add(payment_id)
            try:
                amount = parse_cents(amount_text)
            except ValueError:
                amount = None
                reasons.append("malformed_amount")
            if invoice_id not in invoices:
                reasons.append("unknown_invoice_id")
            if reasons:
                rejected.append(fields + [";".join(reasons)])
                continue
            balances[invoice_id] -= amount
    return balances, rejected


def write_csv_atomic(path, header, rows):
    fd, temporary = tempfile.mkstemp(prefix=".%s." % os.path.basename(path), dir=BASE, text=True)
    try:
        with os.fdopen(fd, "w", newline="", encoding="utf-8") as output:
            writer = csv.writer(output, lineterminator="\n")
            writer.writerow(header)
            writer.writerows(rows)
            output.flush()
            os.fsync(output.fileno())
        os.chmod(temporary, 0o644)
        os.replace(temporary, path)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise


def main():
    invoices, order = load_invoices()
    balances, rejected = reconcile(invoices)
    write_csv_atomic(BALANCES, ["invoice_id", "outstanding_cents"],
                     ((invoice_id, balances[invoice_id]) for invoice_id in order))
    write_csv_atomic(REJECTED,
                     ["payment_id", "invoice_id", "amount_cents", "reason"],
                     rejected)


if __name__ == "__main__":
    main()
ANTRIEB_RECONCILE_EOF
